  /** The `colorBy` members each layer coloured by one draws, every one at first. */
  private readonly kept: ReadonlyMap<string, WritableSignal<readonly string[]>>;

  /** Each layer's state, in declared order. A getter over signals: a view reading it follows every change. */
  get layers(): readonly MapLayerState[] {
    return this.state();
  }

  /** The zoom the map stands at, `null` while no map is shown under the handle. A getter over a signal: a view reading it follows every camera move. */
  get zoom(): number | null {
    return this.zoomShown();
  }

  /** `Map.sketch`: the map draws *geometry* into its sketch source in place of what it sketched; `null` clears it. */
  sketch(geometry: object | null): void {
    this.sketchShown.set(geometry);
  }

  /** The geometry the map draws into its sketch source, `null` for none. A signal read: the map redraws when a sketch changes it. */
  sketched(): object | null {
    return this.sketchShown();
  }

  /** Moves the camera so it shows *bounds*. */
  fit(bounds: GeoBounds): void {
    this.attached()?.fit(bounds);
  }

  /** Flies the camera to *point* at *zoom*. */
  flyTo(point: GeoPoint, zoom: number): void {
    this.attached()?.flyTo(point, zoom);
  }

  /** `Map.basemap`: switches the map to the basemap *name*, one of its `basemaps(...)`. */
  basemap(name: string): void {
    this.attached()?.basemap(name);
  }

  /** Shows or hides the layer the map declares as *layer*. */
  show(layer: string, visible: boolean): void {
    this.layerNamed(layer).visible.set(visible);
  }

  /** Re-runs the data binding of the layer the map declares as *layer*; nothing for a layer no binding reads. */
